        public const string LOV_MFF_ACTIVE_LOAN = """
        select concat(l."LOAN_ACCOUNT_NO", ' - ', a."APPLICATION_NO") "D", l."LOAN_ID" "R"
        from "MFF_LOANS" l
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        where l."LOAN_STATUS" in ('ACTIVE', 'DELINQUENT')
        order by l."LOAN_ACCOUNT_NO"
        """;

        public const string LOV_MFF_ALLOWED_TRANSITION = """
        select coalesce(s."NAME_EN", s."NAME_AR") "D", t."TO_STATUS_CODE" "R"
        from "MFF_LKP_STATUS_TRANSITIONS" t
        join "MFF_LKP_APPLICATION_STATUSES" s on s."CODE" = t."TO_STATUS_CODE"
        where t."FROM_STATUS_CODE" = @P29_CURRENT_STATUS::text and t."IS_ACTIVE" and (t."ROLE_CODE" is null or t."ROLE_CODE" = @P29_ROLE_CODE::text)
        order by s."DISPLAY_ORDER"
        """;

        public const string LOV_MFF_APPLICATION = """
        select concat(a."APPLICATION_NO", ' - ', coalesce(p."FULL_NAME_AR", '?')) "D", a."APPLICATION_ID" "R"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        order by a."APPLICATION_ID" desc
        """;

        public const string LOV_MFF_APPLICATION_DOCUMENT = """
        select concat(coalesce(t."NAME_EN", t."NAME_AR"), ' - ', coalesce(d."FILE_NAME", concat('#', d."DOCUMENT_ID"))) "D", d."DOCUMENT_ID" "R"
        from "MFF_APPLICATION_DOCUMENTS" d
        left join "MFF_LKP_DOCUMENT_TYPES" t on t."CODE" = d."DOCUMENT_TYPE_CODE"
        where d."APPLICATION_ID" = @P54_APPLICATION_ID::bigint
        order by d."DOCUMENT_ID" desc
        """;

        public const string LOV_MFF_CASE_STATUS = """
        select 'Open' "D", 'OPEN' "R", 1 "SEQ"
        union all select 'In Progress', 'IN_PROGRESS', 2
        union all select 'Closed', 'CLOSED', 3
        union all select 'Cured', 'CURED', 4
        order by "SEQ"
        """;

        public const string LOV_MFF_CHECK_RESULT = """
        select 'Pass' "D", 'PASS' "R", 1 "SEQ"
        union all select 'Warning' "D", 'WARN' "R", 2 "SEQ"
        union all select 'Fail' "D", 'FAIL' "R", 3 "SEQ"
        union all select 'Override' "D", 'OVERRIDE' "R", 4 "SEQ"
        order by "SEQ"
        """;

        public const string LOV_MFF_CITY = """
        select concat(coalesce("NAME_EN", "NAME_AR"), ' (', "CODE", ')') "D", "CODE" "R"
        from "MFF_LKP_CITYS"
        where "IS_ACTIVE"
        order by "GOVERNORATE_CODE", "DISPLAY_ORDER", "NAME_AR"
        """;

        public const string LOV_MFF_CONTRACT_STATUS = """
        select 'Draft' "D", 'DRAFT' "R", 1 "SEQ"
        union all select 'Signed', 'SIGNED', 2
        union all select 'Cancelled', 'CANCELLED', 3
        order by "SEQ"
        """;

        public const string LOV_MFF_CREDIT_BUREAU = """
        select coalesce("ORG_NAME_EN", "ORG_NAME_AR") "D", "ORG_ID" "R"
        from "MFF_ORGANIZATIONS"
        where "ORG_TYPE_CODE" = 'CREDIT_BUREAU' and "IS_ACTIVE"
        order by 1
        """;

        public const string LOV_MFF_CREDIT_INQUIRY_RESULT = """
        select 'Accepted' "D", 'PASS' "R", 1 "SEQ"
