        public const string P141_FUND_MONTHLY_REPORT_REPORT = """
        with "MFF_VW_FUND_MONTHLY_REPORT" AS (
        select l."APPLICATION_ID", a."APPLICATION_NO", l."LOAN_ID", l."LOAN_ACCOUNT_NO", a."FINANCIER_ID", f."ORG_NAME_AR" "FINANCIER_NAME_AR", 'DELINQUENCY' "REPORT_EVENT_TYPE", d."START_DATE" "EVENT_DATE", (d."DAYS_PAST_DUE")::text "EVENT_VALUE", d."COLLECTION_ACTION_AR" "EVENT_DETAILS_AR"
        from "MFF_DELINQUENCIES" d
        join "MFF_LOANS" l on l."LOAN_ID" = d."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        union all select l."APPLICATION_ID", a."APPLICATION_NO", l."LOAN_ID", l."LOAN_ACCOUNT_NO", a."FINANCIER_ID", f."ORG_NAME_AR", 'LEGAL_ACTION', la."ACTION_DATE", la."LEGAL_ACTION_STATUS" AS "STATUS", la."OUTCOME_AR"
        from "MFF_LEGAL_ACTIONS" la
        join "MFF_LOANS" l on l."LOAN_ID" = la."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        union all select l."APPLICATION_ID", a."APPLICATION_NO", l."LOAN_ID", l."LOAN_ACCOUNT_NO", a."FINANCIER_ID", f."ORG_NAME_AR", 'EARLY_SETTLEMENT', es."REQUEST_DATE", es."SETTLEMENT_TYPE", es."NOTES_AR"
        from "MFF_EARLY_SETTLEMENTS" es
        join "MFF_LOANS" l on l."LOAN_ID" = es."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        union all select l."APPLICATION_ID", a."APPLICATION_NO", l."LOAN_ID", l."LOAN_ACCOUNT_NO", a."FINANCIER_ID", f."ORG_NAME_AR", e."EVENT_TYPE_CODE", e."EVENT_DATE", e."LOAN_EVENT_STATUS" AS "STATUS", e."DETAILS_AR"
        from "MFF_LOAN_EVENTS" e
        join "MFF_LOANS" l on l."LOAN_ID" = e."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        )
        select "APPLICATION_NO", "LOAN_ACCOUNT_NO", "FINANCIER_NAME_AR", "REPORT_EVENT_TYPE", "EVENT_DATE", "EVENT_VALUE", "EVENT_DETAILS_AR"
        from "MFF_VW_FUND_MONTHLY_REPORT"
        order by "EVENT_DATE" desc, "APPLICATION_NO"
        """;

        public const string P142_PORTFOLIO_SUMMARY_REPORT = """
        with "MFF_VW_MIS_PORTFOLIO_SUMMARY" AS (
        select date_trunc('month', s."SNAPSHOT_MONTH_DATE")::date "SNAPSHOT_MONTH", a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", o."ORG_TYPE_CODE", s."LOAN_STATUS", count(*) "LOAN_COUNT", sum(s."OUTSTANDING_PRINCIPAL") "OUTSTANDING_PRINCIPAL", sum(s."OVERDUE_AMOUNT") "OVERDUE_AMOUNT", sum(s."SUBSIDY_BALANCE") "SUBSIDY_BALANCE", sum(case when s."DAYS_PAST_DUE" > 0 then 1 else 0 end) "DELINQUENT_LOAN_COUNT"
        from "MFF_LOAN_MONTHLY_SNAPSHOTS" s
        join "MFF_LOANS" l on l."LOAN_ID" = s."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        group by date_trunc('month', s."SNAPSHOT_MONTH_DATE")::date, a."FINANCIER_ID", o."ORG_NAME_AR", o."ORG_TYPE_CODE", s."LOAN_STATUS"
        )
        select "SNAPSHOT_MONTH", "FINANCIER_NAME_AR", "ORG_TYPE_CODE", "LOAN_STATUS", "LOAN_COUNT", "OUTSTANDING_PRINCIPAL", "OVERDUE_AMOUNT", "SUBSIDY_BALANCE", "DELINQUENT_LOAN_COUNT"
        from "MFF_VW_MIS_PORTFOLIO_SUMMARY"
        order by "SNAPSHOT_MONTH" desc, "FINANCIER_NAME_AR", "LOAN_STATUS"
        """;

        public const string P143_DELINQUENCY_MIS_REPORT = """
        with "MFF_VW_MIS_DELINQUENCY" AS (
        select a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", d."STAGE_CODE", s."NAME_AR" "STAGE_NAME_AR", count(distinct d."LOAN_ID") "LOAN_COUNT", sum(coalesce(d."OVERDUE_AMOUNT", 0)) "OVERDUE_AMOUNT", sum(coalesce(l."OUTSTANDING_PRINCIPAL", 0)) "OUTSTANDING_PRINCIPAL"
        from "MFF_DELINQUENCIES" d
        join "MFF_LOANS" l on l."LOAN_ID" = d."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        join "MFF_LKP_DELINQUENCY_STAGES" s on s."CODE" = d."STAGE_CODE"
        where coalesce(d."DELINQUENCY_STATUS", 'OPEN') <> 'CLOSED'
        group by a."FINANCIER_ID", o."ORG_NAME_AR", d."STAGE_CODE", s."NAME_AR"
        )
        select "FINANCIER_NAME_AR", "STAGE_CODE", "STAGE_NAME_AR", "LOAN_COUNT", "OVERDUE_AMOUNT", "OUTSTANDING_PRINCIPAL"
        from "MFF_VW_MIS_DELINQUENCY"
        order by "FINANCIER_NAME_AR", "STAGE_CODE"
        """;

        public const string P144_ORIGINATION_FUNNEL_REPORT = """
        with "MFF_VW_MIS_FUNNEL" AS (
        select date_trunc('month', a."APPLICATION_DATE")::date "APPLICATION_MONTH", a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", o."ORG_TYPE_CODE", a."STATUS_CODE", s."NAME_AR" "STATUS_NAME_AR", count(*) "APPLICATION_COUNT", sum(coalesce(a."REQUESTED_FINANCE_AMOUNT", 0)) "REQUESTED_AMOUNT", sum(coalesce(a."APPROVED_FINANCE_AMOUNT", 0)) "APPROVED_AMOUNT"
        from "MFF_APPLICATIONS" a
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        join "MFF_LKP_APPLICATION_STATUSES" s on s."CODE" = a."STATUS_CODE"
        group by date_trunc('month', a."APPLICATION_DATE")::date, a."FINANCIER_ID", o."ORG_NAME_AR", o."ORG_TYPE_CODE", a."STATUS_CODE", s."NAME_AR"
        )
        select "APPLICATION_MONTH", "FINANCIER_NAME_AR", "ORG_TYPE_CODE", "STATUS_CODE", "STATUS_NAME_AR", "APPLICATION_COUNT", "REQUESTED_AMOUNT", "APPROVED_AMOUNT"
        from "MFF_VW_MIS_FUNNEL"
        order by "APPLICATION_MONTH" desc, "FINANCIER_NAME_AR", "STATUS_CODE"
        """;

        public const string P145_TURNAROUND_TIME_REPORT = """
        with "MFF_VW_MIS_TAT" AS (
        with h as (select "APPLICATION_ID", min(case when "NEW_STATUS_CODE" = 'CREDIT_APPROVED' then cast("CHANGED_AT" as date) end) "CREDIT_APPROVAL_DATE", min(case when "NEW_STATUS_CODE" = 'DISBURSED' then cast("CHANGED_AT" as date) end) "DISBURSEMENT_DATE"
        from "MFF_APPLICATION_STATUS_HIST"
        group by "APPLICATION_ID") select a."APPLICATION_ID", a."APPLICATION_NO", a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", a."APPLICATION_DATE", h."CREDIT_APPROVAL_DATE", h."DISBURSEMENT_DATE", case when h."CREDIT_APPROVAL_DATE" is not null then h."CREDIT_APPROVAL_DATE" - a."APPLICATION_DATE" end "DAYS_TO_CREDIT_APPROVAL", case when h."DISBURSEMENT_DATE" is not null then h."DISBURSEMENT_DATE" - a."APPLICATION_DATE" end "DAYS_TO_DISBURSEMENT"
        from "MFF_APPLICATIONS" a
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        left join h h on h."APPLICATION_ID" = a."APPLICATION_ID"
        )
        select "APPLICATION_NO", "FINANCIER_NAME_AR", "APPLICATION_DATE", "CREDIT_APPROVAL_DATE", "DISBURSEMENT_DATE", "DAYS_TO_CREDIT_APPROVAL", "DAYS_TO_DISBURSEMENT"
        from "MFF_VW_MIS_TAT"
        order by "APPLICATION_DATE" desc
        """;

        public const string P146_SUBSIDY_MIS_REPORT = """
        with "MFF_VW_MIS_SUBSIDY" AS (
        select a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", a."PROGRAM_VERSION_ID", pv."PROGRAM_CODE", sa."SUPPORT_TYPE_CODE", count(*) "APPROVAL_COUNT", sum(coalesce(sa."INSTALLMENT_SUPPORT_NPV", 0)) "INSTALLMENT_SUPPORT_NPV", sum(coalesce(sa."DOWNPAYMENT_SUPPORT", 0)) "DOWNPAYMENT_SUPPORT", sum(coalesce(sa."TOTAL_SUPPORT", 0)) "TOTAL_SUPPORT"
        from "MFF_SUBSIDY_APPROVALS" sa
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = sa."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        join "MFF_PROGRAM_VERSIONS" pv on pv."PROGRAM_VERSION_ID" = a."PROGRAM_VERSION_ID"
        group by a."FINANCIER_ID", o."ORG_NAME_AR", a."PROGRAM_VERSION_ID", pv."PROGRAM_CODE", sa."SUPPORT_TYPE_CODE"
        )
        select "FINANCIER_NAME_AR", "PROGRAM_CODE", "SUPPORT_TYPE_CODE", "APPROVAL_COUNT", "INSTALLMENT_SUPPORT_NPV", "DOWNPAYMENT_SUPPORT", "TOTAL_SUPPORT"
        from "MFF_VW_MIS_SUBSIDY"
        order by "FINANCIER_NAME_AR", "PROGRAM_CODE", "SUPPORT_TYPE_CODE"
        """;

        public const string P147_GEOGRAPHY_MIS_REPORT = """
        with "MFF_VW_MIS_GEOGRAPHY" AS (
        select pr."GOVERNORATE_CODE", g."NAME_AR" "GOVERNORATE_NAME_AR", pr."CITY_CODE", c."NAME_AR" "CITY_NAME_AR", a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", count(distinct a."APPLICATION_ID") "APPLICATION_COUNT", sum(coalesce(a."APPROVED_FINANCE_AMOUNT", 0)) "APPROVED_FINANCE_AMOUNT", sum(coalesce(a."TOTAL_SUBSIDY_AMOUNT", 0)) "SUBSIDY_AMOUNT"
        from "MFF_APPLICATIONS" a
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        join "MFF_APPLICATION_PROPERTYS" ap on ap."APPLICATION_ID" = a."APPLICATION_ID" and ap."IS_SELECTED"
        join "MFF_PROPERTIES" pr on pr."PROPERTY_ID" = ap."PROPERTY_ID"
        left join "MFF_LKP_GOVERNORATES" g on g."CODE" = pr."GOVERNORATE_CODE"
        left join "MFF_LKP_CITYS" c on c."CODE" = pr."CITY_CODE"
        group by pr."GOVERNORATE_CODE", g."NAME_AR", pr."CITY_CODE", c."NAME_AR", a."FINANCIER_ID", o."ORG_NAME_AR"
        )
        select "GOVERNORATE_NAME_AR", "CITY_NAME_AR", "FINANCIER_NAME_AR", "APPLICATION_COUNT", "APPROVED_FINANCE_AMOUNT", "SUBSIDY_AMOUNT"
        from "MFF_VW_MIS_GEOGRAPHY"
        order by "GOVERNORATE_NAME_AR", "CITY_NAME_AR", "FINANCIER_NAME_AR"
        """;

        public const string P150_FUND_BATCH_RECONCILIATION = """
        with stg as (select "BATCH_ID", count(*) "ACTUAL_ROW_COUNT", sum(case when "VALIDATION_STATUS" = 'VALID' then 1 else 0 end) "ACTUAL_VALID_COUNT", sum(case when "VALIDATION_STATUS" <> 'VALID' or "VALIDATION_STATUS" is null then 1 else 0 end) "ACTUAL_ERROR_COUNT", sum(case when "APPLICATION_ID" is not null then 1 else 0 end) "IMPORTED_ROW_COUNT"
        from "MFF_IMPORT_STAGINGS"
        group by "BATCH_ID") select b."BATCH_ID", b."FILE_NAME", cast(b."RECEIVED_AT" as date) "RECEIVED_DATE", pv."PROGRAM_CODE", pv."VERSION_NO", f."ORG_NAME_AR" "FINANCIER_NAME_AR", fund."ORG_NAME_AR" "FUND_NAME_AR", b."BATCH_STATUS", b."ROW_COUNT" "STORED_ROW_COUNT", coalesce(stg."ACTUAL_ROW_COUNT", 0) "ACTUAL_ROW_COUNT", b."VALID_COUNT" "STORED_VALID_COUNT", coalesce(stg."ACTUAL_VALID_COUNT", 0) "ACTUAL_VALID_COUNT", b."ERROR_COUNT" "STORED_ERROR_COUNT", coalesce(stg."ACTUAL_ERROR_COUNT", 0) "ACTUAL_ERROR_COUNT", coalesce(stg."IMPORTED_ROW_COUNT", 0) "IMPORTED_ROW_COUNT", case when coalesce(b."ROW_COUNT", 0) = coalesce(stg."ACTUAL_ROW_COUNT", 0) and coalesce(b."VALID_COUNT", 0) = coalesce(stg."ACTUAL_VALID_COUNT", 0) and coalesce(b."ERROR_COUNT", 0) = coalesce(stg."ACTUAL_ERROR_COUNT", 0) then 'MATCHED' else 'MISMATCH' end "RECONCILIATION_STATUS", b."NOTES"
        from "MFF_IMPORT_BATCHES" b
        join "MFF_PROGRAM_VERSIONS" pv on pv."PROGRAM_VERSION_ID" = b."PROGRAM_VERSION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = b."FINANCIER_ID"
        join "MFF_ORGANIZATIONS" fund on fund."ORG_ID" = b."FUND_ORG_ID"
        left join stg on stg."BATCH_ID" = b."BATCH_ID" where (@P150_DATE_FROM::date is null or (cast(b."RECEIVED_AT" as date))::date >= @P150_DATE_FROM::date) and (@P150_DATE_TO::date is null or (cast(b."RECEIVED_AT" as date))::date <= @P150_DATE_TO::date) and (@P150_PROGRAM_VERSION_ID::bigint is null or b."PROGRAM_VERSION_ID" = @P150_PROGRAM_VERSION_ID::bigint) and (@P150_FINANCIER_ID::bigint is null or b."FINANCIER_ID" = @P150_FINANCIER_ID::bigint) and (@P150_FUND_ORG_ID::bigint is null or b."FUND_ORG_ID" = @P150_FUND_ORG_ID::bigint) and (@P150_BATCH_STATUS::text is null or b."BATCH_STATUS" = @P150_BATCH_STATUS::text) and (@P150_RECON_STATUS::text is null or case when coalesce(b."ROW_COUNT", 0) = coalesce(stg."ACTUAL_ROW_COUNT", 0) and coalesce(b."VALID_COUNT", 0) = coalesce(stg."ACTUAL_VALID_COUNT", 0) and coalesce(b."ERROR_COUNT", 0) = coalesce(stg."ACTUAL_ERROR_COUNT", 0) then 'MATCHED' else 'MISMATCH' end = @P150_RECON_STATUS::text)
        order by b."RECEIVED_AT" desc, b."BATCH_ID" desc
        """;

        public const string P151_FUND_STAGING_DATA_QUALITY_EXCEPTIONS = """
        select s."STAGING_ID", s."BATCH_ID", b."FILE_NAME", s."SOURCE_ROW_NO", s."APPLICANT_NAME_AR", s."APPLICANT_NATIONAL_ID", s."MONTHLY_INCOME", s."CUSTOMER_DOWNPAYMENT", s."TOTAL_SUBSIDY", s."UNIT_PRICE", s."FINANCE_AMOUNT", s."ANNOUNCEMENT_RAW", s."PROJECT_RAW", s."GOVERNORATE_RAW", s."CITY_RAW", s."AREA_SQM", s."MOBILE_NO", s."VALIDATION_STATUS", s."ERROR_MESSAGE", s."APPLICATION_ID", case when s."APPLICATION_ID" is not null then 'IMPORTED' when s."VALIDATION_STATUS" = 'VALID' then 'READY' else 'REQUIRES_REVIEW' end "PROCESSING_STATE"
        from "MFF_IMPORT_STAGINGS" s
        join "MFF_IMPORT_BATCHES" b on b."BATCH_ID" = s."BATCH_ID" where (@P151_BATCH_ID::bigint is null or s."BATCH_ID" = @P151_BATCH_ID::bigint) and (@P151_VALIDATION_STATUS::text is null or s."VALIDATION_STATUS" = @P151_VALIDATION_STATUS::text) and (@P151_GOVERNORATE::text is null or s."GOVERNORATE_RAW" = @P151_GOVERNORATE::text) and (@P151_PROJECT::text is null or s."PROJECT_RAW" = @P151_PROJECT::text) and (@P151_HAS_ERROR::text is null or (@P151_HAS_ERROR::text = 'Y' and s."ERROR_MESSAGE" is not null) or (@P151_HAS_ERROR::text = 'N' and s."ERROR_MESSAGE" is null))
        order by s."BATCH_ID" desc, s."SOURCE_ROW_NO"
        """;

        public const string P152_APPLICATION_PIPELINE_AGING_DETAIL = """
        with "MFF_VW_APPLICATION_360" AS (
        with last_decision as (select d.*, row_number() over (partition by d."APPLICATION_ID"
        order by d."DECISION_DATE" desc, d."DECISION_ID" desc) "RN"
        from "MFF_CREDIT_DECISIONS" d), last_inquiry as (select q.*, row_number() over (partition by q."APPLICATION_ID"
        order by q."RESPONSE_DATE" desc nulls last, q."INQUIRY_ID" desc) "RN"
        from "MFF_CREDIT_INQUIRIES" q) select a."APPLICATION_ID", a."APPLICATION_NO", a."APPLICATION_DATE", a."STATUS_CODE", s."NAME_AR" "STATUS_NAME_AR", p."PERSON_ID", p."FULL_NAME_AR" "APPLICANT_NAME_AR", p."NATIONAL_ID", p."MARITAL_STATUS_CODE", p."EMPLOYMENT_TYPE_CODE", a."MONTHLY_INCOME_TOTAL", a."PROPERTY_PRICE", a."DOWNPAYMENT_AMOUNT", a."REQUESTED_FINANCE_AMOUNT", a."APPROVED_FINANCE_AMOUNT", a."TOTAL_SUBSIDY_AMOUNT", f."ORG_ID" "FINANCIER_ID", f."ORG_NAME_AR" "FINANCIER_NAME_AR", f."ORG_TYPE_CODE" "FINANCIER_TYPE_CODE", f."REGULATOR_CODE", fund."ORG_NAME_AR" "FUND_NAME_AR", pv."PROGRAM_CODE", pv."VERSION_NO" "PROGRAM_VERSION_NO", hp."PROJECT_NAME_AR", pr."GOVERNORATE_CODE", pr."CITY_CODE", pr."AREA_SQM", pr."SALE_PRICE", pr."APPRAISED_VALUE", "ld"."DECISION_CODE" "LAST_DECISION_CODE", "ld"."DECISION_DATE" "LAST_DECISION_DATE", "li"."CREDIT_SCORE" "LAST_CREDIT_SCORE", "li"."RESULT_CODE" "LAST_CREDIT_INQUIRY_RESULT", a."CURRENT_OWNER_USER", a."BRANCH_CODE"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        join "MFF_ORGANIZATIONS" fund on fund."ORG_ID" = a."FUND_ORG_ID"
        join "MFF_PROGRAM_VERSIONS" pv on pv."PROGRAM_VERSION_ID" = a."PROGRAM_VERSION_ID"
        join "MFF_LKP_APPLICATION_STATUSES" s on s."CODE" = a."STATUS_CODE"
        left join "MFF_APPLICATION_PROPERTYS" ap on ap."APPLICATION_ID" = a."APPLICATION_ID" and ap."IS_SELECTED"
        left join "MFF_PROPERTIES" pr on pr."PROPERTY_ID" = ap."PROPERTY_ID"
        left join "MFF_HOUSING_PROJECTS" hp on hp."PROJECT_ID" = pr."PROJECT_ID"
        left join last_decision ld on "ld"."APPLICATION_ID" = a."APPLICATION_ID" and "ld"."RN" = 1
        left join last_inquiry li on "li"."APPLICATION_ID" = a."APPLICATION_ID" and "li"."RN" = 1
        ),
         status_age as (select a."APPLICATION_ID", max(cast(h."CHANGED_AT" as date)) "STATUS_ENTERED_DATE"
        from "MFF_APPLICATIONS" a
        left join "MFF_APPLICATION_STATUS_HIST" h on h."APPLICATION_ID" = a."APPLICATION_ID" and h."NEW_STATUS_CODE" = a."STATUS_CODE"
        group by a."APPLICATION_ID") select v."APPLICATION_ID", v."APPLICATION_NO", v."APPLICANT_NAME_AR", v."FINANCIER_NAME_AR", v."PROGRAM_CODE", v."STATUS_CODE", v."STATUS_NAME_AR", v."APPLICATION_DATE", coalesce("sa"."STATUS_ENTERED_DATE", v."APPLICATION_DATE") "STATUS_ENTERED_DATE", current_date - (coalesce("sa"."STATUS_ENTERED_DATE", v."APPLICATION_DATE"))::date "DAYS_IN_STATUS", v."REQUESTED_FINANCE_AMOUNT", v."APPROVED_FINANCE_AMOUNT", v."TOTAL_SUBSIDY_AMOUNT", v."CURRENT_OWNER_USER", v."BRANCH_CODE"
        from "MFF_VW_APPLICATION_360" v
        left join status_age sa on "sa"."APPLICATION_ID" = v."APPLICATION_ID" where (@P152_STATUS_CODE::text is null or v."STATUS_CODE" = @P152_STATUS_CODE::text) and (@P152_FINANCIER_ID::numeric is null or v."FINANCIER_ID" = @P152_FINANCIER_ID::numeric) and (@P152_PROGRAM_VERSION_ID::bigint is null or exists (select 1
        from "MFF_APPLICATIONS" a
        where a."APPLICATION_ID" = v."APPLICATION_ID" and a."PROGRAM_VERSION_ID" = @P152_PROGRAM_VERSION_ID::bigint)) and (@P152_OWNER_USER::text is null or v."CURRENT_OWNER_USER" = @P152_OWNER_USER::text) and (@P152_MIN_DAYS_IN_STATUS::numeric is null or current_date - (coalesce("sa"."STATUS_ENTERED_DATE", v."APPLICATION_DATE"))::date >= @P152_MIN_DAYS_IN_STATUS::numeric)
        order by "DAYS_IN_STATUS" desc, v."APPLICATION_DATE"
        """;

        public const string P153_APPLICANT_INCOME_AND_AFFORDABILITY_CONTROL = """
        with income_totals as (select ap."APPLICATION_ID", sum(coalesce(i."MONTHLY_NET_INCOME", 0)) "SOURCE_MONTHLY_INCOME", sum(case when i."IS_VERIFIED" then coalesce(i."MONTHLY_NET_INCOME", 0) else 0 end) "VERIFIED_SOURCE_INCOME"
        from "MFF_APPLICATION_PARTIES" ap
        join "MFF_INCOME_SOURCES" i on i."APPLICATION_PARTY_ID" = ap."APPLICATION_PARTY_ID"
        where coalesce(ap."IS_INCOME_INCLUDED", true)
        group by ap."APPLICATION_ID"), study as (select x.* from (select cs.*, row_number() over (partition by cs."APPLICATION_ID"
        order by cs."STUDY_DATE" desc, cs."CREDIT_STUDY_ID" desc) "RN"
        from "MFF_CREDIT_STUDIES" cs) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", p."NATIONAL_ID", p."EMPLOYMENT_TYPE_CODE", o."ORG_NAME_AR" "FINANCIER_NAME_AR", a."STATUS_CODE", a."MONTHLY_INCOME_TOTAL" "DECLARED_MONTHLY_INCOME", coalesce("it"."SOURCE_MONTHLY_INCOME", 0) "SOURCE_MONTHLY_INCOME", coalesce("it"."VERIFIED_SOURCE_INCOME", 0) "VERIFIED_SOURCE_INCOME", "st"."VERIFIED_INCOME_AMOUNT" "CREDIT_VERIFIED_INCOME", "st"."MONTHLY_OBLIGATIONS_AMOUNT", "st"."DISPOSABLE_INCOME_AMOUNT", "st"."INSTALLMENT_INCOME_PCT", "st"."LTV_PCT", a."REQUESTED_FINANCE_AMOUNT", a."APPROVED_FINANCE_AMOUNT", coalesce("it"."VERIFIED_SOURCE_INCOME", 0) - coalesce(a."MONTHLY_INCOME_TOTAL", 0) "INCOME_VARIANCE"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        left join income_totals it on "it"."APPLICATION_ID" = a."APPLICATION_ID"
        left join study st on "st"."APPLICATION_ID" = a."APPLICATION_ID" where (@P153_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P153_FINANCIER_ID::bigint) and (@P153_STATUS_CODE::text is null or a."STATUS_CODE" = @P153_STATUS_CODE::text) and (@P153_EMPLOYMENT_TYPE::text is null or p."EMPLOYMENT_TYPE_CODE" = @P153_EMPLOYMENT_TYPE::text) and (@P153_MIN_INCOME_VARIANCE::numeric is null or abs(coalesce("it"."VERIFIED_SOURCE_INCOME", 0) - coalesce(a."MONTHLY_INCOME_TOTAL", 0)) >= @P153_MIN_INCOME_VARIANCE::numeric) and (@P153_MIN_INSTALLMENT_INCOME_PCT::numeric is null or coalesce("st"."INSTALLMENT_INCOME_PCT", 0) >= @P153_MIN_INSTALLMENT_INCOME_PCT::numeric)
        order by abs(coalesce("it"."VERIFIED_SOURCE_INCOME", 0) - coalesce(a."MONTHLY_INCOME_TOTAL", 0)) desc, a."APPLICATION_NO"
        """;

        public const string P154_REQUIRED_DOCUMENT_COMPLIANCE_AND_EXPIRY = """
        with latest_doc as (select x.* from (select d.*, row_number() over (partition by d."APPLICATION_ID", d."DOCUMENT_TYPE_CODE"
        order by coalesce(cast(d."VERIFIED_AT" as date), d."RECEIVED_DATE") desc nulls last, d."DOCUMENT_ID" desc) "RN"
        from "MFF_APPLICATION_DOCUMENTS" d) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", o."ORG_NAME_AR" "FINANCIER_NAME_AR", a."STATUS_CODE", r."DOCUMENT_TYPE_CODE", dt."NAME_AR" "DOCUMENT_NAME_AR", r."PARTY_ROLE_CODE", r."EMPLOYMENT_TYPE_CODE", d."DOCUMENT_ID", d."DOCUMENT_NO", d."RECEIVED_DATE", d."EXPIRY_DATE", d."VERIFICATION_STATUS", case when d."DOCUMENT_ID" is null then 'MISSING' when coalesce(d."VERIFICATION_STATUS", 'RECEIVED') in ('REJECTED', 'INVALID') then 'REJECTED' when d."EXPIRY_DATE" is not null and d."EXPIRY_DATE" < current_date then 'EXPIRED' when d."EXPIRY_DATE" is not null and d."EXPIRY_DATE" <= current_date + 30 then 'EXPIRING_30' else 'OK' end "COMPLIANCE_STATUS"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        join "MFF_PROGRAM_DOC_REQUIREMENTS" r on r."PROGRAM_VERSION_ID" = a."PROGRAM_VERSION_ID" and r."IS_REQUIRED" and current_date between coalesce(r."EFFECTIVE_FROM_DATE", date '1900-01-01') and coalesce(r."EFFECTIVE_TO_DATE", date '2999-12-31')
        join "MFF_LKP_DOCUMENT_TYPES" dt on dt."CODE" = r."DOCUMENT_TYPE_CODE"
        left join latest_doc d on d."APPLICATION_ID" = a."APPLICATION_ID" and d."DOCUMENT_TYPE_CODE" = r."DOCUMENT_TYPE_CODE" where (r."EMPLOYMENT_TYPE_CODE" is null or r."EMPLOYMENT_TYPE_CODE" = p."EMPLOYMENT_TYPE_CODE") and (@P154_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P154_FINANCIER_ID::bigint) and (@P154_DOCUMENT_TYPE::text is null or r."DOCUMENT_TYPE_CODE" = @P154_DOCUMENT_TYPE::text) and (@P154_STATUS_CODE::text is null or a."STATUS_CODE" = @P154_STATUS_CODE::text) and (@P154_EXPIRY_TO::date is null or d."EXPIRY_DATE" <= @P154_EXPIRY_TO::date) and (@P154_COMPLIANCE_STATUS::text is null or case when d."DOCUMENT_ID" is null then 'MISSING' when coalesce(d."VERIFICATION_STATUS", 'RECEIVED') in ('REJECTED', 'INVALID') then 'REJECTED' when d."EXPIRY_DATE" is not null and d."EXPIRY_DATE" < current_date then 'EXPIRED' when d."EXPIRY_DATE" is not null and d."EXPIRY_DATE" <= current_date + 30 then 'EXPIRING_30' else 'OK' end = @P154_COMPLIANCE_STATUS::text)
        order by a."APPLICATION_NO", r."DOCUMENT_TYPE_CODE"
        """;

        public const string P155_CREDIT_INQUIRY_SLA_AND_EXCEPTION = """
        select q."INQUIRY_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", p."NATIONAL_ID", f."ORG_NAME_AR" "FINANCIER_NAME_AR", bureau."ORG_NAME_AR" "BUREAU_NAME_AR", q."REQUEST_DATE", q."RESPONSE_DATE", case when q."RESPONSE_DATE" is null then current_date - (q."REQUEST_DATE")::date else (q."RESPONSE_DATE")::date - (q."REQUEST_DATE")::date end "TURNAROUND_DAYS", q."CREDIT_SCORE", q."RESULT_CODE", q."REFERENCE_NO", case when q."RESPONSE_DATE" is null then 'PENDING' when (q."RESPONSE_DATE")::date - (q."REQUEST_DATE")::date > coalesce(@P155_SLA_DAYS::numeric, 2) then 'SLA_BREACH' else 'WITHIN_SLA' end "SLA_STATUS", q."NOTES"
        from "MFF_CREDIT_INQUIRIES" q
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = q."APPLICATION_ID"
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        left join "MFF_ORGANIZATIONS" bureau on bureau."ORG_ID" = q."BUREAU_ORG_ID" where (@P155_DATE_FROM::text is null or q."REQUEST_DATE" >= (@P155_DATE_FROM::text)::date) and (@P155_DATE_TO::text is null or q."REQUEST_DATE" < (@P155_DATE_TO::text)::date + 1) and (@P155_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P155_FINANCIER_ID::bigint) and (@P155_BUREAU_ORG_ID::bigint is null or q."BUREAU_ORG_ID" = @P155_BUREAU_ORG_ID::bigint) and (@P155_RESULT_CODE::text is null or q."RESULT_CODE" = @P155_RESULT_CODE::text) and (@P155_OPEN_ONLY::text is null or @P155_OPEN_ONLY::text <> 'Y' or q."RESPONSE_DATE" is null) and (@P155_SLA_DAYS::numeric is null or case when q."RESPONSE_DATE" is null then current_date - (q."REQUEST_DATE")::date else (q."RESPONSE_DATE")::date - (q."REQUEST_DATE")::date end >= @P155_SLA_DAYS::numeric)
        order by "TURNAROUND_DAYS" desc, q."REQUEST_DATE"
        """;

        public const string P156_CREDIT_STUDY_VERSUS_FINAL_DECISION_VARIANCE = """
        with study as (select x.* from (select cs.*, row_number() over (partition by cs."APPLICATION_ID"
        order by cs."STUDY_DATE" desc, cs."CREDIT_STUDY_ID" desc) "RN"
        from "MFF_CREDIT_STUDIES" cs) x
        where x."RN" = 1), decision as (select x.* from (select cd.*, row_number() over (partition by cd."APPLICATION_ID"
        order by cd."DECISION_DATE" desc, cd."DECISION_ID" desc) "RN"
        from "MFF_CREDIT_DECISIONS" cd) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", o."ORG_NAME_AR" "FINANCIER_NAME_AR", "s"."ANALYST_USER", "s"."STUDY_DATE", "s"."RECOMMENDATION_CODE", "s"."PROPOSED_FINANCE_AMOUNT", "s"."PROPOSED_TERM_MONTHS", "s"."PROPOSED_RATE_PCT", "d"."DECISION_CODE", "d"."DECISION_DATE", "d"."APPROVED_FINANCE_AMOUNT", "d"."APPROVED_TERM_MONTHS", "d"."APPROVED_RATE_PCT", "d"."DECIDED_BY", coalesce("d"."APPROVED_FINANCE_AMOUNT", 0) - coalesce("s"."PROPOSED_FINANCE_AMOUNT", 0) "AMOUNT_VARIANCE", coalesce("d"."APPROVED_TERM_MONTHS", 0) - coalesce("s"."PROPOSED_TERM_MONTHS", 0) "TERM_VARIANCE_MONTHS", coalesce("d"."APPROVED_RATE_PCT", 0) - coalesce("s"."PROPOSED_RATE_PCT", 0) "RATE_VARIANCE_PCT", "d"."CONDITIONS_TEXT"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
        join study s on "s"."APPLICATION_ID" = a."APPLICATION_ID"
        join decision d on "d"."APPLICATION_ID" = a."APPLICATION_ID" where (@P156_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P156_FINANCIER_ID::bigint) and (@P156_DECISION_CODE::text is null or "d"."DECISION_CODE" = @P156_DECISION_CODE::text) and (@P156_ANALYST_USER::text is null or "s"."ANALYST_USER" = @P156_ANALYST_USER::text) and (@P156_DATE_FROM::text is null or "d"."DECISION_DATE" >= (@P156_DATE_FROM::text)::date) and (@P156_DATE_TO::text is null or "d"."DECISION_DATE" < (@P156_DATE_TO::text)::date + 1) and (@P156_VARIANCE_ONLY::text is null or @P156_VARIANCE_ONLY::text <> 'Y' or coalesce("d"."APPROVED_FINANCE_AMOUNT", 0) <> coalesce("s"."PROPOSED_FINANCE_AMOUNT", 0) or coalesce("d"."APPROVED_TERM_MONTHS", 0) <> coalesce("s"."PROPOSED_TERM_MONTHS", 0) or coalesce("d"."APPROVED_RATE_PCT", 0) <> coalesce("s"."PROPOSED_RATE_PCT", 0))
        order by "d"."DECISION_DATE" desc, a."APPLICATION_NO"
        """;

        public const string P157_PROPERTY_VALUATION_AND_LTV_RISK_REPORT = """
        with appraisal as (select x.* from (select ap.*, row_number() over (partition by ap."APPLICATION_ID", ap."PROPERTY_ID"
        order by ap."REPORT_DATE" desc nulls last, ap."APPRAISAL_ID" desc) "RN"
        from "MFF_APPRAISALS" ap) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", f."ORG_NAME_AR" "FINANCIER_NAME_AR", pr."PROPERTY_ID", hp."PROJECT_NAME_AR", pr."GOVERNORATE_CODE", pr."CITY_CODE", pr."AREA_SQM", pr."SALE_PRICE", pr."APPRAISED_VALUE" "PROPERTY_APPRAISED_VALUE", "av"."MARKET_VALUE", "av"."FORCED_SALE_VALUE", "av"."ACCEPTED_VALUE", "av"."APPRAISER_NAME", appr_org."ORG_NAME_AR" "APPRAISER_ORG_NAME_AR", "av"."REPORT_DATE", "av"."APPRAISAL_STATUS", a."APPROVED_FINANCE_AMOUNT", round(100 * coalesce(a."APPROVED_FINANCE_AMOUNT", 0) / (nullif(coalesce("av"."ACCEPTED_VALUE", coalesce(pr."APPRAISED_VALUE", pr."SALE_PRICE")), 0))::numeric, 2) "CALCULATED_LTV_PCT", coalesce("av"."ACCEPTED_VALUE", coalesce(pr."APPRAISED_VALUE", pr."SALE_PRICE")) - coalesce(pr."SALE_PRICE", 0) "VALUE_VARIANCE"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        join "MFF_APPLICATION_PROPERTYS" ap on ap."APPLICATION_ID" = a."APPLICATION_ID" and ap."IS_SELECTED"
        join "MFF_PROPERTIES" pr on pr."PROPERTY_ID" = ap."PROPERTY_ID"
        left join "MFF_HOUSING_PROJECTS" hp on hp."PROJECT_ID" = pr."PROJECT_ID"
        left join appraisal av on "av"."APPLICATION_ID" = a."APPLICATION_ID" and "av"."PROPERTY_ID" = pr."PROPERTY_ID"
        left join "MFF_ORGANIZATIONS" appr_org on appr_org."ORG_ID" = "av"."APPRAISER_ORG_ID" where (@P157_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P157_FINANCIER_ID::bigint) and (@P157_GOVERNORATE_CODE::text is null or pr."GOVERNORATE_CODE" = @P157_GOVERNORATE_CODE::text) and (@P157_APPRAISER_ORG_ID::numeric is null or "av"."APPRAISER_ORG_ID" = @P157_APPRAISER_ORG_ID::numeric) and (@P157_APPRAISAL_STATUS::text is null or "av"."APPRAISAL_STATUS" = @P157_APPRAISAL_STATUS::text) and (@P157_MIN_LTV_PCT::numeric is null or round(100 * coalesce(a."APPROVED_FINANCE_AMOUNT", 0) / (nullif(coalesce("av"."ACCEPTED_VALUE", coalesce(pr."APPRAISED_VALUE", pr."SALE_PRICE")), 0))::numeric, 2) >= @P157_MIN_LTV_PCT::numeric)
        order by "CALCULATED_LTV_PCT" desc nulls last, a."APPLICATION_NO"
        """;

        public const string P158_CALCULATOR_VERSUS_APPROVED_OFFERED_TERMS = """
        with calc as (select x.* from (select c.*, row_number() over (partition by c."APPLICATION_ID"
        order by c."CALC_RUN_ID" desc) "RN"
        from "MFF_CALCULATION_RUNS" c
        where c."APPLICATION_ID" is not null) x
        where x."RN" = 1), offer as (select x.* from (select o.*, row_number() over (partition by o."APPLICATION_ID"
        order by o."OFFER_DATE" desc, o."OFFER_ID" desc) "RN"
        from "MFF_FINANCE_OFFERS" o) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", f."ORG_NAME_AR" "FINANCIER_NAME_AR", c."RUN_TYPE", c."CALC_STATUS", c."OUT_MORTGAGE_LOAN" "CALC_MORTGAGE_LOAN", c."OUT_INITIAL_PAYMENT" "CALC_INITIAL_PAYMENT", c."OUT_LTV_PCT" "CALC_LTV_PCT", a."APPROVED_FINANCE_AMOUNT", o."OFFER_NO", o."OFFER_DATE", o."FINANCE_AMOUNT" "OFFER_FINANCE_AMOUNT", o."TERM_MONTHS" "OFFER_TERM_MONTHS", o."ANNUAL_RATE_PCT" "OFFER_RATE_PCT", o."INITIAL_INSTALLMENT" "OFFER_INITIAL_INSTALLMENT", o."LTV_PCT" "OFFER_LTV_PCT", coalesce(o."FINANCE_AMOUNT", 0) - coalesce(c."OUT_MORTGAGE_LOAN", 0) "OFFER_VS_CALC_AMOUNT_VARIANCE", coalesce(a."APPROVED_FINANCE_AMOUNT", 0) - coalesce(c."OUT_MORTGAGE_LOAN", 0) "APPROVAL_VS_CALC_AMOUNT_VARIANCE"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        join calc c on c."APPLICATION_ID" = a."APPLICATION_ID"
        left join offer o on o."APPLICATION_ID" = a."APPLICATION_ID" where (@P158_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P158_FINANCIER_ID::bigint) and (@P158_PROGRAM_VERSION_ID::bigint is null or c."PROGRAM_VERSION_ID" = @P158_PROGRAM_VERSION_ID::bigint) and (@P158_RUN_TYPE::text is null or c."RUN_TYPE" = @P158_RUN_TYPE::text) and (@P158_MIN_AMOUNT_VARIANCE::numeric is null or abs(coalesce(o."FINANCE_AMOUNT", 0) - coalesce(c."OUT_MORTGAGE_LOAN", 0)) >= @P158_MIN_AMOUNT_VARIANCE::numeric) and (@P158_VARIANCE_ONLY::text is null or @P158_VARIANCE_ONLY::text <> 'Y' or coalesce(o."FINANCE_AMOUNT", 0) <> coalesce(c."OUT_MORTGAGE_LOAN", 0) or coalesce(a."APPROVED_FINANCE_AMOUNT", 0) <> coalesce(c."OUT_MORTGAGE_LOAN", 0) or coalesce(o."LTV_PCT", 0) <> coalesce(c."OUT_LTV_PCT", 0))
        order by abs(coalesce(o."FINANCE_AMOUNT", 0) - coalesce(c."OUT_MORTGAGE_LOAN", 0)) desc, a."APPLICATION_NO"
        """;

        public const string P159_SUBSIDY_APPROVAL_AND_ACCOUNT_UTILIZATION = """
        with mov as (select "SUBSIDY_ACCOUNT_ID", count(*) "MOVEMENT_COUNT", sum(coalesce("AMOUNT", 0)) "MOVEMENT_AMOUNT_TOTAL", min("MOVEMENT_DATE") "FIRST_MOVEMENT_DATE", max("MOVEMENT_DATE") "LAST_MOVEMENT_DATE"
        from "MFF_SUBSIDY_MOVEMENTS"
        group by "SUBSIDY_ACCOUNT_ID") select a."APPLICATION_ID", a."APPLICATION_NO", f."ORG_NAME_AR" "FINANCIER_NAME_AR", fund."ORG_NAME_AR" "FUND_NAME_AR", sa."SUPPORT_TYPE_CODE", sa."APPROVAL_NO", sa."APPROVAL_DATE", sa."EXPIRY_DATE", sa."INSTALLMENT_SUPPORT_NPV", sa."DOWNPAYMENT_SUPPORT", sa."TOTAL_SUPPORT" "APPROVED_TOTAL_SUPPORT", sa."APPROVAL_STATUS", l."LOAN_ACCOUNT_NO", sacc."ACCOUNT_NO" "SUBSIDY_ACCOUNT_NO", sacc."OPEN_DATE", sacc."OPENING_AMOUNT", sacc."CURRENT_BALANCE", sacc."ACCOUNT_STATUS", coalesce(mov."MOVEMENT_COUNT", 0) "MOVEMENT_COUNT", coalesce(mov."MOVEMENT_AMOUNT_TOTAL", 0) "MOVEMENT_AMOUNT_TOTAL", mov."FIRST_MOVEMENT_DATE", mov."LAST_MOVEMENT_DATE", coalesce(sacc."OPENING_AMOUNT", 0) - coalesce(sa."TOTAL_SUPPORT", 0) "OPENING_VS_APPROVAL_VARIANCE"
        from "MFF_SUBSIDY_APPROVALS" sa
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = sa."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        join "MFF_ORGANIZATIONS" fund on fund."ORG_ID" = a."FUND_ORG_ID"
        left join "MFF_LOANS" l on l."APPLICATION_ID" = a."APPLICATION_ID"
        left join "MFF_SUBSIDY_ACCOUNTS" sacc on sacc."LOAN_ID" = l."LOAN_ID"
        left join mov on mov."SUBSIDY_ACCOUNT_ID" = sacc."SUBSIDY_ACCOUNT_ID" where (@P159_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P159_FINANCIER_ID::bigint) and (@P159_FUND_ORG_ID::bigint is null or a."FUND_ORG_ID" = @P159_FUND_ORG_ID::bigint) and (@P159_APPROVAL_STATUS::text is null or sa."APPROVAL_STATUS" = @P159_APPROVAL_STATUS::text) and (@P159_ACCOUNT_STATUS::text is null or sacc."ACCOUNT_STATUS" = @P159_ACCOUNT_STATUS::text) and (@P159_SUPPORT_TYPE::text is null or sa."SUPPORT_TYPE_CODE" = @P159_SUPPORT_TYPE::text)
        order by sa."APPROVAL_DATE" desc, a."APPLICATION_NO"
        """;

        public const string P160_FINANCE_OFFER_AND_CONTRACT_CONVERSION_REPORT = """
        with offer as (select x.* from (select o.*, row_number() over (partition by o."APPLICATION_ID"
        order by o."OFFER_DATE" desc, o."OFFER_ID" desc) "RN"
        from "MFF_FINANCE_OFFERS" o) x
        where x."RN" = 1), contract as (select x.* from (select c.*, row_number() over (partition by c."APPLICATION_ID"
        order by c."CONTRACT_DATE" desc, c."CONTRACT_ID" desc) "RN"
        from "MFF_CONTRACTS" c) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", f."ORG_NAME_AR" "FINANCIER_NAME_AR", o."OFFER_NO", o."OFFER_DATE", o."EXPIRY_DATE" "OFFER_EXPIRY_DATE", o."FINANCE_AMOUNT" "OFFER_FINANCE_AMOUNT", o."TERM_MONTHS", o."ANNUAL_RATE_PCT", o."OFFER_STATUS", o."ACCEPTED_DATE", c."CONTRACT_NO", c."CONTRACT_DATE", c."CONTRACT_STATUS", c."IS_SIGNED" AS "SIGNED_FLAG", c."FINANCE_AMOUNT" "CONTRACT_FINANCE_AMOUNT", case when c."CONTRACT_ID" is null then 'NO_CONTRACT' when not coalesce(c."IS_SIGNED", false) then 'UNSIGNED' else 'SIGNED' end "CONVERSION_STATUS", case when c."CONTRACT_DATE" is not null then (c."CONTRACT_DATE")::date - (o."OFFER_DATE")::date end "DAYS_OFFER_TO_CONTRACT", case when o."EXPIRY_DATE" is not null then (o."EXPIRY_DATE")::date - current_date end "DAYS_TO_OFFER_EXPIRY"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        join offer o on o."APPLICATION_ID" = a."APPLICATION_ID"
        left join contract c on c."APPLICATION_ID" = a."APPLICATION_ID" where (@P160_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P160_FINANCIER_ID::bigint) and (@P160_OFFER_STATUS::text is null or o."OFFER_STATUS" = @P160_OFFER_STATUS::text) and (@P160_CONTRACT_STATUS::text is null or c."CONTRACT_STATUS" = @P160_CONTRACT_STATUS::text) and (@P160_EXPIRING_WITHIN_DAYS::integer is null or o."EXPIRY_DATE" between current_date and current_date + @P160_EXPIRING_WITHIN_DAYS::integer) and (@P160_CONVERSION_STATUS::text is null or case when c."CONTRACT_ID" is null then 'NO_CONTRACT' when not coalesce(c."IS_SIGNED", false) then 'UNSIGNED' else 'SIGNED' end = @P160_CONVERSION_STATUS::text)
        order by o."OFFER_DATE" desc, a."APPLICATION_NO"
        """;

        public const string P161_DISBURSEMENT_AND_LOAN_BOOKING_RECONCILIATION_REPORT = """
        with contract as (select x.* from (select c.*, row_number() over (partition by c."APPLICATION_ID"
        order by c."CONTRACT_DATE" desc, c."CONTRACT_ID" desc) "RN"
        from "MFF_CONTRACTS" c) x
        where x."RN" = 1), loan as (select x.* from (select l.*, row_number() over (partition by l."APPLICATION_ID"
        order by l."DISBURSEMENT_DATE" desc nulls last, l."LOAN_ID" desc) "RN"
        from "MFF_LOANS" l) x
        where x."RN" = 1) select a."APPLICATION_ID", a."APPLICATION_NO", p."FULL_NAME_AR" "APPLICANT_NAME_AR", f."ORG_NAME_AR" "FINANCIER_NAME_AR", a."STATUS_CODE", a."APPROVED_FINANCE_AMOUNT", c."CONTRACT_NO", c."CONTRACT_DATE", c."IS_SIGNED" AS "SIGNED_FLAG", c."CONTRACT_STATUS", c."FINANCE_AMOUNT" "CONTRACT_FINANCE_AMOUNT", l."LOAN_ID", l."LOAN_ACCOUNT_NO", l."DISBURSEMENT_DATE", l."PRINCIPAL_AMOUNT" "LOAN_PRINCIPAL_AMOUNT", l."ANNUAL_RATE_PCT", l."TERM_MONTHS", l."MATURITY_DATE", l."LOAN_STATUS", l."CORE_SYSTEM_REF", case when c."CONTRACT_ID" is null then 'MISSING_CONTRACT' when not coalesce(c."IS_SIGNED", false) then 'CONTRACT_NOT_SIGNED' when l."LOAN_ID" is null then 'MISSING_LOAN' when coalesce(l."PRINCIPAL_AMOUNT", 0) <> coalesce(c."FINANCE_AMOUNT", 0) then 'LOAN_CONTRACT_AMOUNT_MISMATCH' when coalesce(l."PRINCIPAL_AMOUNT", 0) <> coalesce(a."APPROVED_FINANCE_AMOUNT", 0) then 'LOAN_APPROVAL_AMOUNT_MISMATCH' else 'OK' end "RECONCILIATION_STATUS"
        from "MFF_APPLICATIONS" a
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        left join contract c on c."APPLICATION_ID" = a."APPLICATION_ID"
        left join loan l on l."APPLICATION_ID" = a."APPLICATION_ID" where (@P161_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P161_FINANCIER_ID::bigint) and (@P161_DATE_FROM::text is null or l."DISBURSEMENT_DATE" >= (@P161_DATE_FROM::text)::date) and (@P161_DATE_TO::text is null or l."DISBURSEMENT_DATE" < (@P161_DATE_TO::text)::date + 1) and (@P161_LOAN_STATUS::text is null or l."LOAN_STATUS" = @P161_LOAN_STATUS::text) and (@P161_EXCEPTION_ONLY::text is null or @P161_EXCEPTION_ONLY::text <> 'Y' or c."CONTRACT_ID" is null or not coalesce(c."IS_SIGNED", false) or l."LOAN_ID" is null or coalesce(l."PRINCIPAL_AMOUNT", 0) <> coalesce(c."FINANCE_AMOUNT", 0) or coalesce(l."PRINCIPAL_AMOUNT", 0) <> coalesce(a."APPROVED_FINANCE_AMOUNT", 0))
        order by l."DISBURSEMENT_DATE" desc nulls last, a."APPLICATION_NO"
        """;

        public const string P162_INSTALLMENT_DUE_AND_CASH_FLOW_FORECAST_REPORT = """
        select date_trunc('month', i."DUE_DATE")::date as "DUE_MONTH", a."FINANCIER_ID", f."ORG_NAME_AR" as "FINANCIER_NAME_AR", l."LOAN_STATUS", i."PAYMENT_STATUS_CODE", count(distinct l."LOAN_ID") as "LOAN_COUNT", count(*) as "INSTALLMENT_COUNT", sum(coalesce(i."BORROWER_DUE", 0)) as "BORROWER_DUE", sum(coalesce(i."SUBSIDY_DUE", 0)) as "SUBSIDY_DUE", sum(coalesce(i."TOTAL_DUE", 0)) as "TOTAL_DUE", sum(coalesce(i."PAID_AMOUNT", 0)) as "PAID_AMOUNT", sum(greatest(coalesce(i."TOTAL_DUE", 0) - coalesce(i."PAID_AMOUNT", 0), 0)) as "OUTSTANDING_DUE"
        from "MFF_INSTALLMENTS" i
        join "MFF_LOANS" l on l."LOAN_ID" = i."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID" where (@P162_DUE_FROM::text is null or i."DUE_DATE" >= (@P162_DUE_FROM::text)::date) and (@P162_DUE_TO::text is null or i."DUE_DATE" < (@P162_DUE_TO::text)::date + interval '1 day') and (@P162_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P162_FINANCIER_ID::bigint) and (@P162_PAYMENT_STATUS::text is null or i."PAYMENT_STATUS_CODE" = @P162_PAYMENT_STATUS::text) and (@P162_LOAN_STATUS::text is null or l."LOAN_STATUS" = @P162_LOAN_STATUS::text)
        group by date_trunc('month', i."DUE_DATE")::date, a."FINANCIER_ID", f."ORG_NAME_AR", l."LOAN_STATUS", i."PAYMENT_STATUS_CODE"
        order by "DUE_MONTH", "FINANCIER_NAME_AR", "LOAN_STATUS", "PAYMENT_STATUS_CODE"
