        public const string P163_COLLECTIONS_ALLOCATION_AND_PAYMENT_PERFORMANCE_REPORT = """
        select pmt."PAYMENT_ID", pmt."PAYMENT_DATE", a."APPLICATION_NO", l."LOAN_ACCOUNT_NO", per."FULL_NAME_AR" as "APPLICANT_NAME_AR", f."ORG_NAME_AR" as "FINANCIER_NAME_AR", pmt."PAYMENT_TYPE", pmt."PAYMENT_CHANNEL", pmt."REFERENCE_NO", pmt."PAYMENT_AMOUNT", pmt."ALLOCATED_PRINCIPAL", pmt."ALLOCATED_INTEREST", pmt."ALLOCATED_FEES", pmt."ALLOCATED_INSURANCE", coalesce(pmt."PAYMENT_AMOUNT", 0) - coalesce(pmt."ALLOCATED_PRINCIPAL", 0) - coalesce(pmt."ALLOCATED_INTEREST", 0) - coalesce(pmt."ALLOCATED_FEES", 0) - coalesce(pmt."ALLOCATED_INSURANCE", 0) as "UNALLOCATED_AMOUNT", pmt."STATUS_CODE"
        from "MFF_PAYMENTS" pmt
        join "MFF_LOANS" l on l."LOAN_ID" = pmt."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_PERSONS" per on per."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID" where (@P163_DATE_FROM::text is null or pmt."PAYMENT_DATE" >= (@P163_DATE_FROM::text)::date) and (@P163_DATE_TO::text is null or pmt."PAYMENT_DATE" < (@P163_DATE_TO::text)::date + 1) and (@P163_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P163_FINANCIER_ID::bigint) and (@P163_PAYMENT_CHANNEL::text is null or pmt."PAYMENT_CHANNEL" = @P163_PAYMENT_CHANNEL::text) and (@P163_STATUS_CODE::text is null or pmt."STATUS_CODE" = @P163_STATUS_CODE::text) and (@P163_UNALLOCATED_ONLY::text is null or @P163_UNALLOCATED_ONLY::text <> 'Y' or abs(coalesce(pmt."PAYMENT_AMOUNT", 0) - coalesce(pmt."ALLOCATED_PRINCIPAL", 0) - coalesce(pmt."ALLOCATED_INTEREST", 0) - coalesce(pmt."ALLOCATED_FEES", 0) - coalesce(pmt."ALLOCATED_INSURANCE", 0)) > 0.01)
        order by pmt."PAYMENT_DATE" desc, pmt."PAYMENT_ID" desc
        """;

        public const string P164_DELINQUENCY_AGING_AND_CURE_REPORT = """
        select d."DELINQUENCY_ID", a."APPLICATION_NO", l."LOAN_ACCOUNT_NO", p."FULL_NAME_AR" as "APPLICANT_NAME_AR", f."ORG_NAME_AR" as "FINANCIER_NAME_AR", d."START_DATE", d."END_DATE", d."STAGE_CODE", st."NAME_AR" as "STAGE_NAME_AR", d."DAYS_PAST_DUE", case when d."DAYS_PAST_DUE" <= 0 then 'CURRENT' when d."DAYS_PAST_DUE" <= 30 then '01-30' when d."DAYS_PAST_DUE" <= 60 then '31-60' when d."DAYS_PAST_DUE" <= 90 then '61-90' when d."DAYS_PAST_DUE" <= 180 then '91-180' else '180+' end as "AGING_BUCKET", d."OVERDUE_AMOUNT", d."OVERDUE_INSTALLMENTS", d."DELINQUENCY_STATUS" AS "STATUS", d."COLLECTION_ACTION_AR", l."OUTSTANDING_PRINCIPAL", case when d."END_DATE" is not null then (d."END_DATE")::date - (d."START_DATE")::date end as "DAYS_TO_CURE"
        from "MFF_DELINQUENCIES" d
        join "MFF_LOANS" l on l."LOAN_ID" = d."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        join "MFF_LKP_DELINQUENCY_STAGES" st on st."CODE" = d."STAGE_CODE" where (@P164_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P164_FINANCIER_ID::bigint) and (@P164_STAGE_CODE::text is null or d."STAGE_CODE" = @P164_STAGE_CODE::text) and (@P164_STATUS::text is null or d."DELINQUENCY_STATUS" = @P164_STATUS::text) and (@P164_MIN_DPD::bigint is null or d."DAYS_PAST_DUE" >= @P164_MIN_DPD::bigint) and (@P164_START_FROM::text is null or d."START_DATE" >= (@P164_START_FROM::text)::date) and (@P164_START_TO::text is null or d."START_DATE" < (@P164_START_TO::text)::date + 1)
        order by d."DAYS_PAST_DUE" desc, d."OVERDUE_AMOUNT" desc
        """;

        public const string P165_EARLY_SETTLEMENT_AND_SUBSIDY_REFUND_CONTROL_REPORT = """
        with subsidy as (select x.* from (select sa.*, row_number() over (partition by sa."APPLICATION_ID"
        order by sa."APPROVAL_DATE" desc, sa."SUBSIDY_APPROVAL_ID" desc) "RN"
        from "MFF_SUBSIDY_APPROVALS" sa) x
        where x."RN" = 1), subsidy_account as (select x.* from (select sacc.*, row_number() over (partition by sacc."LOAN_ID"
        order by sacc."OPEN_DATE" desc, sacc."SUBSIDY_ACCOUNT_ID" desc) "RN"
        from "MFF_SUBSIDY_ACCOUNTS" sacc) x
        where x."RN" = 1) select es."SETTLEMENT_ID", es."REQUEST_DATE", es."SETTLEMENT_DATE", es."SETTLEMENT_TYPE", es."EARLY_SETTLEMENT_STATUS" AS "STATUS", a."APPLICATION_NO", l."LOAN_ACCOUNT_NO", p."FULL_NAME_AR" as "APPLICANT_NAME_AR", f."ORG_NAME_AR" as "FINANCIER_NAME_AR", l."OUTSTANDING_PRINCIPAL", es."PRINCIPAL_SETTLED", es."FINANCE_PCT_SETTLED", es."SUBSIDY_REFUND_PCT", es."SUBSIDY_REFUND_AMOUNT", sa."TOTAL_SUPPORT" as "APPROVED_TOTAL_SUPPORT", sacc."CURRENT_BALANCE" as "SUBSIDY_ACCOUNT_BALANCE", es."APPROVED_BY", es."NOTES_AR"
        from "MFF_EARLY_SETTLEMENTS" es
        join "MFF_LOANS" l on l."LOAN_ID" = es."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID"
        left join subsidy sa on sa."APPLICATION_ID" = a."APPLICATION_ID"
        left join subsidy_account sacc on sacc."LOAN_ID" = l."LOAN_ID" where (@P165_DATE_FROM::text is null or es."REQUEST_DATE" >= (@P165_DATE_FROM::text)::date) and (@P165_DATE_TO::text is null or es."REQUEST_DATE" < (@P165_DATE_TO::text)::date + 1) and (@P165_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P165_FINANCIER_ID::bigint) and (@P165_SETTLEMENT_TYPE::text is null or es."SETTLEMENT_TYPE" = @P165_SETTLEMENT_TYPE::text) and (@P165_STATUS::text is null or es."EARLY_SETTLEMENT_STATUS" = @P165_STATUS::text)
        order by es."REQUEST_DATE" desc, es."SETTLEMENT_ID" desc
        """;

        public const string P166_LOAN_RESTRUCTURING_MONITORING_REPORT = """
        select r."RESTRUCTURING_ID", r."REQUEST_DATE", r."DECISION_DATE", r."EFFECTIVE_DATE", a."APPLICATION_NO", l."LOAN_ACCOUNT_NO", p."FULL_NAME_AR" as "APPLICANT_NAME_AR", f."ORG_NAME_AR" as "FINANCIER_NAME_AR", r."REASON_AR", r."OLD_TERM_MONTHS", r."NEW_TERM_MONTHS", r."NEW_TERM_MONTHS" - r."OLD_TERM_MONTHS" as "TERM_CHANGE_MONTHS", r."OLD_RATE_PCT", r."NEW_RATE_PCT", r."NEW_RATE_PCT" - r."OLD_RATE_PCT" as "RATE_CHANGE_PCT", r."OLD_INSTALLMENT", r."NEW_INSTALLMENT", r."NEW_INSTALLMENT" - r."OLD_INSTALLMENT" as "INSTALLMENT_CHANGE", r."LOAN_RESTRUCTURING_STATUS" AS "STATUS", r."APPROVED_BY", case when r."DECISION_DATE" is not null then (r."DECISION_DATE")::date - (r."REQUEST_DATE")::date else current_date - (r."REQUEST_DATE")::date end as "DECISION_AGE_DAYS", r."NOTES_AR"
        from "MFF_LOAN_RESTRUCTURINGS" r
        join "MFF_LOANS" l on l."LOAN_ID" = r."LOAN_ID"
        join "MFF_APPLICATIONS" a on a."APPLICATION_ID" = l."APPLICATION_ID"
        join "MFF_PERSONS" p on p."PERSON_ID" = a."PRIMARY_PERSON_ID"
        join "MFF_ORGANIZATIONS" f on f."ORG_ID" = a."FINANCIER_ID" where (@P166_FINANCIER_ID::bigint is null or a."FINANCIER_ID" = @P166_FINANCIER_ID::bigint) and (@P166_STATUS::text is null or r."LOAN_RESTRUCTURING_STATUS" = @P166_STATUS::text) and (@P166_REQUEST_FROM::text is null or r."REQUEST_DATE" >= (@P166_REQUEST_FROM::text)::date) and (@P166_REQUEST_TO::text is null or r."REQUEST_DATE" < (@P166_REQUEST_TO::text)::date + interval '1 day') and (@P166_PENDING_ONLY::text is null or @P166_PENDING_ONLY::text <> 'Y' or coalesce(r."LOAN_RESTRUCTURING_STATUS", 'REQUESTED') in ('REQUESTED', 'PENDING'))
        order by r."REQUEST_DATE" desc, r."RESTRUCTURING_ID" desc
        """;
    }
}
